<?php namespace App\Http\Controllers; use App\Models\ProvincialLeader; use Illuminate\Http\Request; use Illuminate\Validation\Rule; class ProvincialLeaderController extends Controller { public function index(){return view('console.leaders',['leaders'=>ProvincialLeader::orderBy('sort_order')->get()]);} public function store(Request $request){ProvincialLeader::create($request->validate(['name'=>'required|max:255','position'=>['required',Rule::in(['gubernur','wakil_gubernur'])],'period'=>'nullable|max:50','vision'=>'nullable','photo_path'=>'nullable|max:255','emblem_path'=>'nullable|max:255','sort_order'=>'nullable|integer']));return back()->with('success','Pimpinan ditambahkan.');} public function destroy(ProvincialLeader $leader){$leader->delete();return back()->with('success','Pimpinan dihapus.');} }
